def compute(vars):
    total_commitments = vars["v2"]
    due_in_2020 = vars["v1"]

    if total_commitments == 0:
        return None

    percentage = due_in_2020 / total_commitments * 100

    return {
        "value": percentage,
        "trace": {
            "due_in_2020": due_in_2020,
            "total_commitments": total_commitments,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
